from import_export import resources
from tablib import Dataset
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from rest_framework.exceptions import PermissionDenied
from .models import WarehouseInventoryItem

class ScopedInventoryItemResource(resources.ModelResource):
    def __init__(self, warehouse=None, **kwargs):
        super().__init__(**kwargs)
        self.warehouse = warehouse

    def get_queryset(self):
        return WarehouseInventoryItem.objects.filter(warehouse=self.warehouse)

    def init_instance(self, row=None):
        instance = super().init_instance(row=row)
        instance.warehouse = self.warehouse
        return instance

    class Meta:
        model = WarehouseInventoryItem
        import_id_fields = ('id',)
        fields = ('id', 'sku', 'quantity_in_stock', 'bin_location', 'unit_cost')

class ConfirmInventoryImportView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def post(self, request):
        raw_data = request.FILES.get('file')
        if not raw_data:
            return Response({'error': 'No file uploaded'}, status=status.HTTP_400_BAD_REQUEST)

        user_warehouse = getattr(request.user, 'warehouse', None)
        if not user_warehouse:
            raise PermissionDenied("User is not assigned to a warehouse.")

        dataset = Dataset().load(raw_data.read().decode('utf-8'), format='csv')
        resource = ScopedInventoryItemResource(warehouse=user_warehouse)
        result = resource.import_data(dataset, dry_run=False, raise_errors=True)

        return Response({
            'status': 'imported',
            'totals': result.totals,
            'has_errors': result.has_errors()
        })
